// Writes src/css/words.rs: the words that the big alternations of the `css`
// grammar spell out, expanded, lower-cased and sorted, so a matcher can test a
// whole word against a list. Every list is matched without regard to case.
//
// Run with `bun run oracle/css-words.ts`, then `cargo +nightly-2026-11-01 fmt
// --all`, and commit the result; the output is generated, do not edit it.
import css from "@shikijs/langs@4.6.0/css";

import { expand } from "./alternation.ts";

type Node = { match?: string; begin?: string; patterns?: Node[] };
const repository = (css as unknown as { repository: Record<string, Node> }[])[0]!.repository;

/** The regex of the `index`th pattern of repository entry `key`, or of the entry itself. */
function regexOf(key: string, index?: number): string {
  const node = index === undefined ? repository[key]! : repository[key]!.patterns![index]!;
  return (node.match ?? node.begin)!;
}

/** The words of the first group (or `(?:` group) that follows `prefix` in `regex`. */
function words(regex: string, prefix: string, suffix: string): string[] {
  const start = regex.indexOf(prefix);
  if (start < 0) throw new Error(`${prefix} not in ${regex.slice(0, 60)}`);
  const body = regex.slice(start + prefix.length, regex.lastIndexOf(suffix));
  return [...new Set(expand(body).map((w) => w.toLowerCase()))].sort();
}

const lists: [string, string[]][] = [
  ["PROPERTY_NAMES", words(regexOf("property-names", 0), "(?<![-\\w])(?:", ")(?![-\\w])")],
  ["PROPERTY_KEYWORDS", words(regexOf("property-keywords", 0), "(?<![-\\w])(", ")(?![-\\w])")],
  ["LIST_STYLES", words(regexOf("property-keywords", 1), "(?<![-\\w])(", ")(?![-\\w])")],
  ["FONT_FAMILIES", words(regexOf("property-keywords", 3), "(?<![-\\w])(?i:", ")(?![-\\w])")],
  ["COLORS_STANDARD", words(regexOf("color-keywords", 0), "(?<![-\\w])(", ")(?![-\\w])")],
  ["COLORS_EXTENDED", words(regexOf("color-keywords", 1), "(?<![-\\w])(", ")(?![-\\w])")],
  ["COLORS_SYSTEM", words(regexOf("color-keywords", 3), "(?<![-\\w])(", ")(?![-\\w])")],
  ["TAG_NAMES", words(regexOf("tag-names"), "(?<![-:\\w])(?:", ")(?=[#")],
  ["FUNCTIONS", words(regexOf("functions", 4), "(?<![-\\w])(", ")(\\()")],
  ["FUNCTION_COLORS", words(regexOf("functions", 1), "(?<![-\\w])(", ")(\\()")],
  ["FUNCTION_GRADIENTS", words(regexOf("functions", 2), "(?<![-\\w])(", ")(\\()")],
  ["FUNCTION_TRANSFORMS", words(regexOf("functions", 7), "(?<![-\\w])(", ")(\\()")],
  ["PSEUDO_CLASSES", words(regexOf("pseudo-classes"), "(:)(:*)(?:", ")(?![-\\w]|\\s*[;}])")],
  ["PSEUDO_ELEMENTS", words(regexOf("pseudo-elements"), "(?:(::?)(?:", "|(?:-(?:")],
  ["PSEUDO_ELEMENTS_DOUBLE", words(regexOf("pseudo-elements"), "|(::)(?:", "))(?![-\\w]|\\s*[;}])")],
  ["VENDORS", words(regexOf("pseudo-elements"), "|(?:-(?:", ")|(?:mso|prince))-")],
];

let out = `//! The words that the big alternations of the \`css\` grammar spell out, lower
//! case and sorted. Generated by \`oracle/css-words.ts\`; do not edit.

`;
for (const [name, list] of lists) {
  out += `pub(super) const ${name}: &[&str] = &[\n${list.map((w) => `    ${JSON.stringify(w)},\n`).join("")}];\n\n`;
}
const root = new URL("..", import.meta.url).pathname;
await Bun.write(`${root}src/css/words.rs`, out.trimEnd() + "\n");
console.log(lists.map(([n, l]) => `${n} ${l.length}`).join(", "));
